	font-size: 1.5em;
	font-weight: bold;
	color: #2e7d32;
	margin-top: 5px;
}

.dashboard-container .time-chart {
	display: flex;
	justify-content: space-between;
	align-items: end;
	height: 120px;
	margin-top: 20px;
	padding: 0 10px;
}

.dashboard-container .time-bar {
	flex: 1;
	margin: 0 2px;
	background: #c8e6c9;
	border-radius: 5px 5px 0 0;
	display: flex;
	flex-direction: column;
	justify-content: end;
	align-items: center;
	padding: 5px 2px;
	transition: background 0.3s ease;
}

.dashboard-container .time-bar.current {
	background: #4caf50;
	color: white;
}

.dashboard-container .time-bar-value {
	font-size: 0.8em;
	font-weight: bold;
	margin-bottom: 5px;
}

.dashboard-container .time-bar-label {
	font-size: 0.7em;
	writing-mode: vertical-lr;
}

.dashboard-container .notification-feed {
	max-height: 200px;
	overflow-y: auto;
	margin-top: 15px;
}

.dashboard-container .notification-item {
	padding: 10px;
	margin-bottom: 8px;
	background: #f1f8e9;
	border-radius: 8px;
	border-left: 4px solid #4caf50;
	animation: slideIn 0.5s ease;
}

.dashboard-container .notification-item.new {
	background: #e8f5e8;
	animation: pulse 2s ease-in-out;
}

@keyframes slideIn {
	from { opacity: 0; transform: translateX(-20px); }
	to { opacity: 1; transform: translateX(0); }
}

@keyframes pulse {
	0%, 100% { background: #e8f5e8; }
	50% { background: #c8e6c9; }
}

.dashboard-container .notification-time {
	font-size: 0.8em;
	color: #666;
	float: right;
}

.dashboard-container .smile-meter {
	text-align: center;
	margin-top: 20px;
}

.dashboard-container .smile-faces {
	font-size: 2em;
	margin: 10px 0;
}

.dashboard-container .smile-value {
	font-size: 1.5em;
	font-weight: bold;
	color: #ff9800;
}

@media (max-width: 768px) {
	.dashboard-container .dashboard-grid {
		grid-template-columns: 1fr;
	}
	
	.dashboard-container .header h1 {
		font-size: 1.8em;
	}
	
	.dashboard-container .metric-value {
		font-size: 2em;
	}
	
	.dashboard-container .region-grid {
		grid-template-columns: repeat(2, 1fr);
	}
}

@media (max-width: 480px) {
	.dashboard-container .dashboard-container {
		padding: 10px;
	}
	
	.dashboard-container .card {
		padding: 15px;
	}
	
	.dashboard-container .header h1 {
		font-size: 1.5em;
	}
}
