/* ============================================
   장바구니 담기 재미있는 효과
   ============================================ */

/* 숫자 뱃지 팝 애니메이션 */
@keyframes cartBadgePop {
    0% { transform: scale(0); }
    50% { transform: scale(1.4); }
    70% { transform: scale(0.9); }
    100% { transform: scale(1); }
}

@keyframes cartBadgeBounce {
    0%, 100% { transform: translateY(0); }
    25% { transform: translateY(-8px); }
    50% { transform: translateY(0); }
    75% { transform: translateY(-4px); }
}

/* 체크마크 애니메이션 */
@keyframes checkmarkDraw {
    0% { stroke-dashoffset: 24; }
    100% { stroke-dashoffset: 0; }
}

/* 물결 효과 */
@keyframes cartRipple {
    0% { transform: scale(0); opacity: 0.6; }
    100% { transform: scale(2.5); opacity: 0; }
}

/* 버튼 전체 바운스 */
@keyframes cartButtonBounce {
    0% { transform: scale(1); }
    30% { transform: scale(0.95); }
    50% { transform: scale(1.02); }
    100% { transform: scale(1); }
}

/* 장바구니 버튼 추가 스타일 */
.product_cart_full,
.review_cart_btn {
    position: relative !important;
    overflow: hidden !important;
}

.product_cart_full.adding,
.review_cart_btn.adding {
    animation: cartButtonBounce 0.4s ease !important;
}

.product_cart_full .cart-count.show,
.review_cart_btn .cart_count.active {
    animation: cartBadgePop 0.4s ease forwards !important;
}

.product_cart_full.added .cart-count.show,
.review_cart_btn.added .cart_count.active {
    animation: cartBadgeBounce 0.5s ease !important;
}

/* 물결 효과 요소 */
.cart-ripple {
    position: absolute !important;
    width: 40px !important;
    height: 40px !important;
    background: rgba(74, 124, 49, 0.3) !important;
    border-radius: 50% !important;
    pointer-events: none !important;
    animation: cartRipple 0.6s ease-out forwards !important;
}

/* 체크 아이콘 */
.cart-check-icon {
    display: none;
    width: 18px !important;
    height: 18px !important;
    margin-right: 4px !important;
}

.product_cart_full.added .cart-check-icon,
.review_cart_btn.added .cart-check-icon {
    display: inline-block !important;
}

.cart-check-icon path {
    stroke: #5a8648 !important;
    stroke-width: 3 !important;
    stroke-linecap: round !important;
    stroke-linejoin: round !important;
    fill: none !important;
    stroke-dasharray: 24 !important;
    stroke-dashoffset: 24 !important;
    animation: checkmarkDraw 0.3s ease forwards 0.1s !important;
}

/* 성공 토스트 메시지 */
.cart-toast {
    position: fixed !important;
    top: 50% !important;
    left: 50% !important;
    transform: translate(-50%, -50%) scale(0.8) !important;
    background: rgba(0, 0, 0, 0.9) !important;
    color: #fff !important;
    padding: 30px 50px !important;
    border-radius: 20px !important;
    font-size: 16px !important;
    font-weight: 600 !important;
    z-index: 99999 !important;
    opacity: 0 !important;
    pointer-events: none !important;
    transition: all 0.3s ease !important;
    text-align: center !important;
    min-width: 280px !important;
    box-shadow: 0 10px 40px rgba(0,0,0,0.3) !important;
}

.cart-toast.show {
    opacity: 1 !important;
    transform: translate(-50%, -50%) scale(1) !important;
}

.cart-toast .toast-icon {
    display: block !important;
    width: 60px !important;
    height: 60px !important;
    margin: 0 auto 15px !important;
    background: #5a8648 !important;
    border-radius: 50% !important;
    line-height: 60px !important;
    font-size: 28px !important;
}

.cart-toast span {
    display: block !important;
    color: #fff !important;
    visibility: visible !important;
    opacity: 1 !important;
}

.cart-toast .toast-text {
    display: block !important;
    color: #ffffff !important;
    font-size: 18px !important;
    font-weight: 600 !important;
    line-height: 1.4 !important;
    visibility: visible !important;
    opacity: 1 !important;
    margin-top: 10px !important;
}

.cart-toast .toast-subtext {
    display: block !important;
    margin-top: 10px !important;
    font-size: 14px !important;
    color: rgba(255,255,255,0.8) !important;
    font-weight: 400 !important;
    visibility: visible !important;
    opacity: 1 !important;
}

