    color: #D84C3F;
}
.product-card-standard .card-price .price-final {
    font-size: 24px;
    font-weight: 700;
    color: #1D271E;
}
.product-card-standard .card-price .won {
    font-size: 15px;
    font-weight: 500;
}

/* 카드 설명 영역 */
.product-card-standard .card-desc {
    padding: 14px 20px;
    background: #F8F9FA;
    min-height: 70px;
}
.product-card-standard .card-desc ul {
    margin: 0;
    padding: 0;
    list-style: none;
}
.product-card-standard .card-desc li {
    position: relative;
    padding-left: 18px;
    font-size: 13px;
    color: #555;
    line-height: 1.5;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}
.product-card-standard .card-desc li:before {
    content: '✓';
    position: absolute;
    left: 0;
    top: 0;
    color: #4A7C31;
    font-size: 12px;
    font-weight: 600;
}
.product-card-standard .card-desc li + li {
    margin-top: 4px;
}

/* 카드 장바구니 버튼 */
.product-card-standard .card-cart {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    width: 100%;
    height: 48px;
    background: #5a8648;
    border: none;
    border-radius: 0 0 12px 12px;
    color: #fff;
    font-size: 15px;
    font-weight: 500;
    cursor: pointer;
    transition: background 0.2s;
}
.product-card-standard .card-cart:hover {
    background: #2d4a31;
}
.product-card-standard .card-cart .cart-icon {
    width: 18px;
    height: 18px;
    fill: none;
    stroke: #fff;
    stroke-width: 2;
}

/* 반응형: 태블릿 */
@media (max-width: 1200px) {
    .product-grid-standard {
        grid-template-columns: repeat(3, 1fr);
        gap: 20px;
