/* -----------------------------------------
   11. 슬라이더용 카드 스타일
   ----------------------------------------- */
.std-slider {
    position: relative;
    padding: 0;
    overflow: hidden;
}
.std-slider .swiper-slide {
    width: calc((100% - 60px) / 4);
    flex-shrink: 0;
}
.std-slider .btn_prev,
.std-slider .btn_next {
    position: absolute;
    top: 50%;
    transform: translateY(-50%);
    z-index: 10;
    width: 40px;
    height: 40px;
    cursor: pointer;
}
.std-slider .btn_prev {
    left: 0;
}
.std-slider .btn_next {
    right: 0;
}

/* 슬라이더 반응형 */
@media screen and (max-width: 1200px) {
    .std-slider .swiper-slide {
        width: calc((100% - 40px) / 3);
    }
}
@media screen and (max-width: 900px) {
    .std-slider .swiper-slide {
        width: calc((100% - 20px) / 2);
    }
}
@media screen and (max-width: 600px) {
    .std-slider .swiper-slide {
        width: 100%;
    }
}

