/* ========================================
   토스트 알림 스타일
   ======================================== */
.toast_wrap {
    position: fixed;
    bottom: 30px;
    right: 30px;
    z-index: 10000;
    min-width: 320px;
    max-width: 400px;
    background: #fff;
    border-radius: 12px;
    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.15), 0 2px 8px rgba(0, 0, 0, 0.1);
    transform: translateX(120%);
    opacity: 0;
    transition: all 0.4s cubic-bezier(0.68, -0.55, 0.265, 1.55);
    overflow: hidden;
}

.toast_wrap.show {
    transform: translateX(0);
    opacity: 1;
}

.toast_wrap.hide {
    transform: translateX(120%);
    opacity: 0;
}

.toast_content {
    display: flex;
    align-items: center;
    padding: 16px 20px;
    gap: 14px;
    border-bottom: 1px solid #f0f0f0;
}

.toast_icon {
    width: 40px;
    height: 40px;
    background: linear-gradient(135deg, #4CAF50 0%, #45a049 100%);
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
}

.toast_icon svg {
    color: #fff;
}

.toast_text {
    flex: 1;
}

.toast_msg {
    font-size: 15px;
    font-weight: 600;
    color: #333;
    margin: 0;
    line-height: 1.4;
}

.toast_close {
    width: 32px;
    height: 32px;
    border: none;
    background: #f5f5f5;
    border-radius: 50%;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: all 0.2s;
    flex-shrink: 0;
}

.toast_close:hover {
    background: #e0e0e0;
}

.toast_close svg {
    color: #666;
}

.toast_btns {
    display: flex;
    padding: 0;
}

.toast_btns a {
    flex: 1;
    text-align: center;
    padding: 14px 16px;
    font-size: 14px;
    font-weight: 600;
    text-decoration: none;
    transition: all 0.2s;
}

.toast_btns .btn_continue {
    background: #f8f8f8;
    color: #666;
    border-right: 1px solid #f0f0f0;
}

.toast_btns .btn_continue:hover {
    background: #f0f0f0;
    color: #333;
}

.toast_btns .btn_cart {
    background: #5a8648;
    color: #fff;
}

.toast_btns .btn_cart:hover {
    background: #2d4a31;
}

/* 토스트 진행바 애니메이션 */
.toast_wrap::after {
    content: '';
    position: absolute;
    bottom: 0;
    left: 0;
    height: 3px;
    width: 100%;
    background: linear-gradient(90deg, #4CAF50, #8BC34A);
    transform: scaleX(1);
    transform-origin: left;
}

.toast_wrap.show::after {
    animation: toastProgress 3s linear forwards;
}

@keyframes toastProgress {
    from { transform: scaleX(1); }
    to { transform: scaleX(0); }
}

