/* ========================================
   다중 팝업 레이아웃 (글래스모피즘)
   ======================================== */

/* 배경 오버레이 */
.main_popup_overlay {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: rgba(0, 0, 0, 0.6);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    z-index: 10000;
    animation: fadeIn 0.3s ease;
}

@keyframes fadeIn {
    from { opacity: 0; }
    to { opacity: 1; }
}

/* 팝업 컨테이너 */
.main_popup_container {
    position: fixed;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    z-index: 10001;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 20px;
    animation: popupZoomIn 0.4s cubic-bezier(0.34, 1.56, 0.64, 1);
}

@keyframes popupZoomIn {
    from {
        opacity: 0;
        transform: translate(-50%, -50%) scale(0.8);
    }
    to {
        opacity: 1;
        transform: translate(-50%, -50%) scale(1);
    }
}

/* 팝업 그리드 */
.popup_grid {
    display: flex;
    gap: 20px;
    justify-content: center;
    align-items: flex-start;
}

/* 팝업 개수에 따른 너비 조정 */
.popup_grid.popup_count_1 .popup_item {
    width: 480px;
}

.popup_grid.popup_count_2 .popup_item {
    width: 420px;
}

.popup_grid.popup_count_3 .popup_item {
    width: 360px;
}

/* 개별 팝업 아이템 */
.popup_item {
    background: rgba(255, 255, 255, 0.92);
    backdrop-filter: blur(20px);
    -webkit-backdrop-filter: blur(20px);
    border-radius: 20px;
    border: 1px solid rgba(255, 255, 255, 0.6);
    box-shadow:
        0 25px 50px -12px rgba(0, 0, 0, 0.25),
        0 0 0 1px rgba(255, 255, 255, 0.1) inset;
    overflow: hidden;
    transition: transform 0.3s ease, box-shadow 0.3s ease;
}

.popup_item:hover {
    transform: translateY(-5px);
    box-shadow:
        0 30px 60px -12px rgba(0, 0, 0, 0.3),
        0 0 0 1px rgba(255, 255, 255, 0.1) inset;
}

/* 팝업 컨텐츠 */
.popup_content {
    line-height: 0;
}

.popup_content img {
    width: 100%;
    height: auto;
    display: block;
    border-radius: 20px;
}

.popup_content a {
    display: block;
}

/* 하단 버튼 영역 */
.popup_actions {
    display: flex;
    gap: 12px;
    background: rgba(255, 255, 255, 0.9);
    backdrop-filter: blur(20px);
    -webkit-backdrop-filter: blur(20px);
    padding: 14px 24px;
    border-radius: 50px;
    box-shadow: 0 10px 40px rgba(0, 0, 0, 0.15);
    border: 1px solid rgba(255, 255, 255, 0.5);
}

.popup_actions a {
    padding: 12px 28px;
    font-size: 14px;
    font-weight: 600;
    text-decoration: none;
    border-radius: 25px;
    transition: all 0.2s ease;
}

.popup_actions .btn_today {
    background: rgba(0, 0, 0, 0.05);
    color: #666;
}

.popup_actions .btn_today:hover {
    background: rgba(0, 0, 0, 0.1);
    color: #333;
}

.popup_actions .btn_close_popup {
    background: linear-gradient(135deg, #5a8648 0%, #4a7c4e 100%);
    color: #fff;
    box-shadow: 0 4px 15px rgba(61, 96, 65, 0.3);
}

.popup_actions .btn_close_popup:hover {
    transform: translateY(-2px);
    box-shadow: 0 6px 20px rgba(61, 96, 65, 0.4);
}

/* 반응형 - 태블릿 */
@media screen and (max-width: 1200px) {
    .popup_grid.popup_count_3 .popup_item {
        width: 300px;
    }
    .popup_grid.popup_count_2 .popup_item {
        width: 360px;
    }
}

/* 반응형 - 모바일 */
@media screen and (max-width: 900px) {
    .popup_grid {
        flex-direction: column;
        max-height: 70vh;
        overflow-y: auto;
        padding: 10px;
    }

    .popup_grid.popup_count_1 .popup_item,
    .popup_grid.popup_count_2 .popup_item,
    .popup_grid.popup_count_3 .popup_item {
        width: 90vw;
        max-width: 400px;
    }

    .popup_actions {
        padding: 12px 20px;
    }

    .popup_actions a {
        padding: 10px 20px;
        font-size: 13px;
    }
}

