    gap: 12px !important;
    text-decoration: none !important;
    width: 100% !important;
}

/* 썸네일 이미지 */
.cart_wrap .content_list .img_wrap {
    width: 70px !important;
    height: 70px !important;
    min-width: 70px !important;
    border-radius: 8px !important;
    overflow: hidden !important;
    border: 1px solid #eee !important;
    background: #f9f9f9 !important;
    flex-shrink: 0 !important;
}

.cart_wrap .content_list .img_wrap img {
    width: 100% !important;
    height: 100% !important;
    object-fit: cover !important;
}

/* 상품명 + 단가 */
.cart_wrap .content_list .txt_box {
    flex: 1 !important;
    min-width: 0 !important;
}

.cart_wrap .content_list .txt_box .tt {
    font-size: 14px !important;
    font-weight: 500 !important;
    color: #333 !important;
    line-height: 1.4 !important;
    margin-bottom: 4px !important;
    overflow: hidden !important;
    text-overflow: ellipsis !important;
    white-space: nowrap !important;
}

.cart_wrap .content_list .txt_box .tt:hover {
    color: #5a8648 !important;
}

.cart_wrap .content_list .txt_box .s_price {
    font-size: 13px !important;
    color: #888 !important;
}

.cart_wrap .content_list .txt_box .s_price .org,
.cart_wrap .content_list .txt_box .s_price .sale {
    color: #bbb !important;
    text-decoration: line-through !important;
    font-size: 12px !important;
    margin-right: 4px !important;
}

/* 3. 수량+합계 - grid-area: sumqty */
.cart_wrap .content_list .content .prod_wrap > .sum_quantity {
    grid-area: sumqty !important;
    display: flex !important;
    align-items: center !important;
    gap: 16px !important;
    height: 70px !important;
}

/* 수량 조절기 */
.cart_wrap .spinner_box {
    display: inline-flex !important;
    align-items: center !important;
    background: #fff !important;
    border: 1px solid #ddd !important;
    border-radius: 6px !important;
    overflow: hidden !important;
}

.cart_wrap .spinner_box .minus,
.cart_wrap .spinner_box .plus {
    width: 32px !important;
    height: 32px !important;
    background: #fafafa !important;
    border: none !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    cursor: pointer !important;
    font-size: 0 !important;
}

.cart_wrap .spinner_box .minus:hover,
.cart_wrap .spinner_box .plus:hover {
    background: #eee !important;
}

.cart_wrap .spinner_box .minus img,
.cart_wrap .spinner_box .plus img {
    display: none !important;
}

.cart_wrap .spinner_box .minus::after {
    content: '−' !important;
    font-size: 16px !important;
    color: #555 !important;
}

.cart_wrap .spinner_box .plus::after {
    content: '+' !important;
    font-size: 16px !important;
    color: #555 !important;
}

.cart_wrap .spinner_box .idx {
    border-left: 1px solid #ddd !important;
    border-right: 1px solid #ddd !important;
}

.cart_wrap .spinner_box .idx input {
    width: 40px !important;
    height: 32px !important;
    text-align: center !important;
    font-size: 14px !important;
    font-weight: 600 !important;
    color: #333 !important;
    border: none !important;
    background: #fff !important;
}

/* 4. 합계 금액 (sum_quantity 안) */
.cart_wrap .content_list .b_price {
    min-width: 75px !important;
    text-align: right !important;
    font-size: 15px !important;
    font-weight: 700 !important;
    color: #222 !important;
    white-space: nowrap !important;
}

/* 5. 삭제 버튼 - grid-area: del */
.cart_wrap .content_list .content .prod_wrap > .btn_delete,
.cart_wrap .content_list .content .prod_wrap > button {
    grid-area: del !important;
    position: static !important;
    top: unset !important;
    right: unset !important;
    width: 30px !important;
    height: 30px !important;
    background: #f5f5f5 !important;
    border: none !important;
    border-radius: 50% !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    cursor: pointer !important;
    font-size: 0 !important;
    margin: 0 !important;
    padding: 0 !important;
}

.cart_wrap .content_list .btn_delete:hover {
    background: #ffebee !important;
}

.cart_wrap .content_list .btn_delete::after {
    content: '×' !important;
    font-size: 18px !important;
    font-weight: 300 !important;
    color: #999 !important;
}

.cart_wrap .content_list .btn_delete:hover::after {
    color: #e53935 !important;
}

.cart_wrap .content_list .btn_delete img {
    display: none !important;
}

/* 쿠폰 영역 숨김 */
.cart_wrap .con_coupon_wrap {
    display: none !important;
}

/* ===== 반응형 - 태블릿 ===== */
@media (max-width: 768px) {
    .cart_wrap .content_list .content .prod_wrap {
        grid-template-columns: 36px 1fr auto 28px !important;
        grid-template-areas:
            "chk prod prod del"
            ". sumqty sumqty ." !important;
        gap: 8px !important;
        row-gap: 10px !important;
    }

    .cart_wrap .content_list .content .prod_wrap > .chk_box {
        height: auto !important;
        align-self: start !important;
        padding-top: 8px !important;
    }

    .cart_wrap .content_list .img_wrap {
        width: 56px !important;
        height: 56px !important;
        min-width: 56px !important;
    }

    .cart_wrap .content_list .content .prod_wrap > .sum_quantity {
        justify-content: space-between !important;
        height: auto !important;
    }
}

@media (max-width: 480px) {
    .cart_wrap .content_list .content {
        padding: 14px 0 !important;
    }

    .cart_wrap .content_list .img_wrap {
        width: 50px !important;
        height: 50px !important;
        min-width: 50px !important;
    }

    .cart_wrap .content_list .txt_box .tt {
        font-size: 13px !important;
    }

    .cart_wrap .spinner_box .minus,
    .cart_wrap .spinner_box .plus {
        width: 28px !important;
        height: 28px !important;
    }

    .cart_wrap .spinner_box .idx input {
        width: 36px !important;
        height: 28px !important;
        font-size: 13px !important;
    }

    .cart_wrap .content_list .b_price {
        font-size: 14px !important;
        min-width: 65px !important;
    }
}
